.display-setting-card{border:0;border-radius:8px;box-shadow:0 2px 10px rgba(20,40,60,.08);overflow:hidden}.display-setting-card .panel-heading{padding:15px 20px}.display-setting-card .panel-body{padding:24px}.display-setting-form .form-group{margin-bottom:18px}.display-setting-form label{display:block;margin-bottom:7px;color:#34495e;font-weight:600}.display-setting-form .form-control{width:100%;height:40px;border:1px solid #d5dce3;border-radius:5px;padding:8px 12px}.display-setting-form .select2-container{width:100%!important}.display-setting-form .select2-selection--single{height:40px!important;border:1px solid #d5dce3!important;border-radius:5px!important}.display-setting-form .select2-selection__rendered{line-height:38px!important;padding-left:12px!important}.display-setting-form .select2-selection__arrow{height:38px!important}.display-setting-submit{height:40px;margin-top:27px;font-weight:600}.device-table{margin-top:8px}.device-table thead th{background:#f5f7f9;color:#34495e;font-weight:600}
